REQUIRED_FILES = ['.editorconfig', '.env.example', '.gitignore', 'README.md', 'apps/api/README.md', 'apps/api/migrations/README.md', 'apps/api/src/sinegor/__init__.py', 'apps/api/src/sinegor/api/__init__.py', 'apps/api/src/sinegor/core/__init__.py', 'apps/api/src/sinegor/db/__init__.py', 'apps/api/src/sinegor/integrations/__init__.py', 'apps/api/src/sinegor/integrations/email/__init__.py', 'apps/api/src/sinegor/integrations/storage/__init__.py', 'apps/api/src/sinegor/integrations/telegram/__init__.py', 'apps/api/src/sinegor/integrations/yandex_disk/__init__.py', 'apps/api/src/sinegor/jobs/__init__.py', 'apps/api/src/sinegor/modules/__init__.py', 'apps/api/src/sinegor/modules/agreements/README.md', 'apps/api/src/sinegor/modules/agreements/__init__.py', 'apps/api/src/sinegor/modules/audit/README.md', 'apps/api/src/sinegor/modules/audit/__init__.py', 'apps/api/src/sinegor/modules/auth/README.md', 'apps/api/src/sinegor/modules/auth/__init__.py', 'apps/api/src/sinegor/modules/customers/README.md', 'apps/api/src/sinegor/modules/customers/__init__.py', 'apps/api/src/sinegor/modules/disk/README.md', 'apps/api/src/sinegor/modules/disk/__init__.py', 'apps/api/src/sinegor/modules/notifications/README.md', 'apps/api/src/sinegor/modules/notifications/__init__.py', 'apps/api/src/sinegor/modules/orders/README.md', 'apps/api/src/sinegor/modules/orders/__init__.py', 'apps/api/src/sinegor/modules/retention/README.md', 'apps/api/src/sinegor/modules/retention/__init__.py', 'apps/api/tests/README.md', 'apps/cms/README.md', 'apps/web/README.md', 'contracts/openapi/README.md', 'docs/project-structure.md', 'infra/README.md', 'scripts/README.md', 'tests/e2e/README.md']


def main():
    missing = [name for name in REQUIRED_DIRS if not (ROOT / name).is_dir()]
    missing += [name for name in REQUIRED_FILES if not (ROOT / name).is_file()]
    if missing:
        raise SystemExit("Отсутствуют:\n" + "\n".join(missing))
    print(f"Структура проверена: {len(REQUIRED_DIRS)} каталогов, {len(REQUIRED_FILES)} файлов.")


if __name__ == "__main__":
    main()
